export function trans(key, params) {
  if (!key) return ''
  let d = messages
  for (const p of String(key).split('.')) {
    if (d && typeof d === 'object' && p in d) d = d[p]
    else return key
  }
  let text = typeof d === 'string' ? d : key
  if (params) for (const [k, v] of Object.entries(params)) text = text.replaceAll(':' + k, v)
  return text
}

export default { messages, trans }
